def top_errors(events, count):
    if count <= 0:
        return []

    error_counts = {}
    for level, message in events:
        if level == 'ERROR':
            error_counts[message] = error_counts.get(message, 0) + 1

    sorted_errors = sorted(error_counts.items(), key=lambda x: (-x[1], x[0]))
    return sorted_errors[:count]
```

