def elapsed(start_ns, finish_ns):
    if finish_ns < start_ns:
        raise ValueError("finish_ns must be greater than start_ns")

    # Convert nanoseconds to milliseconds
    elapsed_ms = (finish_ns - start_ns) / 1e6

    # Handle very large integers exactly
    if elapsed_ms > 9999999999999999:
        raise ValueError("Elapsed time is too large to be represented as an integer")

    return int(elapsed_ms)
```

