def summarize_jobs(jobs):
    summary = {}
    for job in jobs:
        status = job.status
        size = job.size
        if status in summary:
            summary[status][0] += 1
            summary[status][1] += size
        else:
            summary[status] = [1, size]
    return {status: (count, total_size) for status, (count, total_size) in summary.items() if total_size != 0}
```

